INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-mp-01','Harvard vs von Neumann Architecture','Easy','ECE','arena','compare','Microprocessors & Controllers','multiple_choice','The Harvard architecture (used in AVR, PIC microcontrollers) differs from von Neumann by having:','{"choices": ["Faster clock speed", "Separate program memory and data memory buses — allows simultaneous instruction fetch and data access, improving throughput", "More registers", "A larger cache"], "correct": 1}'::jsonb,'Harvard: separate instruction and data memory/buses → can fetch next instruction while processing current data access. von Neumann (Princeton): shared bus → von Neumann bottleneck. Most modern CPUs use modified Harvard internally (unified L1 splits into I-cache and D-cache).','{multiple_choice}'::text[],0.82) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-mp-02','RISC vs CISC Instruction Set','Easy','ECE','arena','compare','Microprocessors & Controllers','multiple_choice','RISC (Reduced Instruction Set Computer) microprocessors like ARM differ from CISC (x86) in that:','{"choices": ["RISC has more instructions than CISC", "RISC instructions are all fixed-length, execute in one clock cycle (typically), use load/store architecture — simpler decode, easier pipeline", "CISC is always faster", "RISC requires more memory"], "correct": 1}'::jsonb,'RISC principles: fixed-length instructions, load/store (operations only on registers, not memory), many registers, simple addressing modes → easy pipelining. CISC (x86): variable-length, complex instructions that do multiple operations. Modern x86 internally decodes to RISC-like micro-ops.','{multiple_choice}'::text[],0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-mp-03','Interrupt Latency','Easy','ECE','arena','calculate','Microprocessors & Controllers','multiple_choice','A microcontroller running at 16 MHz has interrupt latency of 5 clock cycles. What is the interrupt latency in nanoseconds?','{"choices": ["5 ns", "312.5 ns", "5 µs", "80 ns"], "correct": 1}'::jsonb,'Clock period = 1/16 MHz = 62.5 ns. Latency = 5 × 62.5 = 312.5 ns. This is the minimum response time between interrupt assertion and first instruction of the ISR executing. Real latency also includes ISR context save overhead.','{multiple_choice}'::text[],0.85) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-mp-04','DMA vs CPU Data Transfer','Easy','ECE','arena','select','Microprocessors & Controllers','multiple_choice','DMA (Direct Memory Access) is used for high-speed peripheral data transfers because:','{"choices": ["DMA is faster than the CPU clock", "DMA controller handles memory-to-peripheral or memory-to-memory transfers without CPU involvement, freeing the CPU to execute other tasks during the transfer", "DMA uses less memory", "DMA provides error correction"], "correct": 1}'::jsonb,'Without DMA: CPU executes read-from-peripheral, write-to-memory for each byte — CPU is fully occupied. With DMA: CPU programs DMA controller (source, destination, count), then DMA transfers all bytes autonomously via the bus. CPU gets an interrupt when complete.','{multiple_choice}'::text[],0.83) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-mp-05','SPI vs I²C Trade-offs','Easy','ECE','arena','compare','Microprocessors & Controllers','multiple_choice','SPI is preferred over I²C when:','{"choices": ["Multiple masters are needed on the bus", "Long cable distances are required", "Maximum data throughput is needed — SPI has no ACK overhead, full-duplex, and can run at 50+ MHz vs I²C maximum of 3.4 MHz (HS mode)", "Fewer wires are preferred"], "correct": 2}'::jsonb,'I²C: 2 wires (SDA, SCL), multi-master, 400 kHz Fast/1 MHz Fast+/3.4 MHz HS, address-based, ACK each byte. SPI: 4+ wires (MOSI, MISO, SCK, CS×N), single-master, 100 MHz+, full-duplex, no overhead. SPI for high-speed (ADC, DAC, display); I²C for moderate speed, many devices, few wires.','{multiple_choice}'::text[],0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-mp-06','Timer PWM Duty Cycle Calculation','Medium','ECE','arena','calculate','Microprocessors & Controllers','multiple_choice','A microcontroller timer operates at f_timer = 1 MHz with 8-bit counter (0–255). PWM frequency = 1 MHz / 256 ≈ 3.906 kHz. For 60% duty cycle, the compare register should be set to:','{"choices": ["60", "153", "102", "200"], "correct": 1}'::jsonb,'For 60% duty: compare = 0.60 × 256 = 153.6 → round to 153. At count < 153: output HIGH; count ≥ 153: output LOW → 153/256 = 59.8% ≈ 60%.','{multiple_choice}'::text[],0.78) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-mp-07','Watchdog Timer Purpose','Medium','ECE','arena','select','Microprocessors & Controllers','multiple_choice','A watchdog timer in an embedded system:','{"choices": ["Measures real-time clock accuracy", "Automatically resets the microcontroller if the firmware fails to periodically refresh (kick) the watchdog within a specified timeout — prevents system lockup from software bugs", "Controls PWM duty cycle", "Monitors battery voltage"], "correct": 1}'::jsonb,'Watchdog: hardware timer that counts down from a preset value. If firmware "kicks" (resets) it before timeout → system continues. If firmware locks up (hangs, infinite loop) → watchdog fires → MCU reset. Essential for reliable embedded systems (medical, industrial).','{multiple_choice}'::text[],0.84) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-mp-08','Von Neumann Bottleneck','Medium','ECE','arena','interpret','Microprocessors & Controllers','multiple_choice','The von Neumann bottleneck refers to:','{"choices": ["The limited number of CPU registers", "The throughput limitation caused by sharing a single bus between instruction fetches and data transfers — the CPU is often idle waiting for memory", "The maximum clock frequency of the processor", "The limited size of the program counter"], "correct": 1}'::jsonb,'In von Neumann architecture, the CPU can only do one memory access per cycle (either fetch instruction OR access data, not both simultaneously). Modern mitigation: cache hierarchy, wide buses, out-of-order execution, prefetching. Harvard arch avoids this for embedded MCUs.','{multiple_choice}'::text[],0.72) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-mp-09','ARM Cortex-M Exception Model','Medium','ECE','arena','interpret','Microprocessors & Controllers','multiple_choice','In ARM Cortex-M, the NVIC (Nested Vectored Interrupt Controller) allows:','{"choices": ["Only one interrupt at a time with no preemption", "64 different interrupt sources maximum", "Configurable interrupt priorities with tail-chaining and preemption — a higher-priority interrupt can preempt a running lower-priority ISR; hardware saves/restores context automatically", "Interrupts only from external pins"], "correct": 2}'::jsonb,'Cortex-M NVIC: up to 240 external interrupts + system exceptions. Programmable 0-255 priority levels. Preemption: high-priority can interrupt low-priority ISR. Tail-chaining: pending interrupt processed without full stack pop/push. Hardware push/pop of 8 registers on interrupt entry.','{multiple_choice}'::text[],0.68) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-mp-10','Memory-Mapped I/O vs Port-Mapped I/O','Medium','ECE','arena','compare','Microprocessors & Controllers','multiple_choice','ARM Cortex-M microcontrollers use memory-mapped I/O, meaning:','{"choices": ["Peripheral registers are accessed using special IN/OUT instructions", "Peripheral registers are mapped to addresses in the same address space as RAM and Flash — accessed with normal load/store (LDR/STR) instructions", "Only DMA can access peripherals", "I/O ports are separate from memory address space"], "correct": 1}'::jsonb,'Memory-mapped I/O: peripheral registers appear at specific addresses (e.g., GPIOA base = 0x40020000). No special instructions needed — normal read/write. x86 uses separate I/O port space (IN/OUT instructions). ARM Cortex-M exclusively uses memory-mapped I/O.','{multiple_choice}'::text[],0.74) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-mp-11','Bit-Banding in ARM Cortex-M','Medium','ECE','arena','interpret','Microprocessors & Controllers','multiple_choice','ARM Cortex-M3/M4 bit-banding allows atomic bit manipulation. A bit-band alias address is calculated as:
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-mp-12','Pipeline Stalls: Data Hazards','Hard','ECE','arena','diagnose','Microprocessors & Controllers','multiple_choice','In a 5-stage pipeline (IF, ID, EX, MEM, WB), instruction I2 needs the result of I1. If I1 is in EX and I2 needs the result in ID, this is:','{"choices": ["A control hazard — branch prediction miss", "A structural hazard — resource conflict", "A data hazard (RAW — Read After Write) — I2 reads a register before I1 has written the result; causes pipeline stall (bubble) unless forwarding/bypassing is used", "Normal pipeline operation"], "correct": 2}'::jsonb,'RAW (Read After Write) hazard: data dependency. Without forwarding: 2 stall cycles. With forwarding: result forwarded from EX/MEM stage output to next stage ALU input — zero stalls for most cases. Compilers also insert NOPs or reorder independent instructions.','{multiple_choice}'::text[],0.65) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-mp-13','Cache Memory: Direct Mapped vs Set-Associative','Hard','ECE','arena','compare','Microprocessors & Controllers','multiple_choice','A 4-way set-associative cache reduces cache miss rate compared to direct-mapped cache of the same size because:','{"choices": ["Set-associative cache has 4× the memory", "Direct-mapped cache has exactly one location per tag — conflict misses occur when multiple addresses map to the same cache line. 4-way gives 4 choices for each set, reducing conflict misses", "Set-associative is faster to access", "Direct-mapped cache has no replacement policy"], "correct": 1}'::jsonb,'Direct-mapped: 1 slot per index → if two frequently used addresses share the same index, they thrash (constantly evict each other). N-way set-associative: N slots per index → N addresses can co-exist. Trade-off: more complex LRU logic, slightly longer access time.','{multiple_choice}'::text[],0.62) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-mp-14','RTOS: Task Priority Inversion','Hard','ECE','arena','diagnose','Microprocessors & Controllers','multiple_choice','Priority inversion in an RTOS occurs when:','{"choices": ["Two tasks have the same priority", "A high-priority task is blocked indefinitely waiting for a resource (mutex) held by a low-priority task, which itself is preempted by a medium-priority task — the medium task blocks the high-priority task indirectly", "The scheduler makes a preemption error", "A task''s priority is changed at runtime"], "correct": 1}'::jsonb,'Classic example: Mars Pathfinder (1997). Solution: Priority Inheritance Protocol — when low-priority task holds mutex needed by high-priority task, temporarily boost low-priority task to high-priority to release the resource quickly. POSIX PTHREAD_PRIO_INHERIT.','{multiple_choice}'::text[],0.58) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-mp-15','Memory Protection Unit (MPU)','Hard','ECE','arena','select','Microprocessors & Controllers','multiple_choice','An ARM Cortex-M MPU is essential in safety-critical embedded systems because:','{"choices": ["It increases CPU clock speed", "It defines memory regions with access permissions — prevents untrusted code from accessing privileged memory, isolates tasks in RTOS to detect stack overflow, and catches invalid memory access (hard fault) rather than silent corruption", "It compresses the firmware code", "It manages DRAM refresh cycles"], "correct": 1}'::jsonb,'MPU regions: up to 16 configurable regions with attributes (read/write/execute, privileged/unprivileged). Task isolation: each RTOS task gets its stack region, MPU configured on context switch. Stack overflow → MPU fault (hard fault) instead of silent data corruption — enabling detection.','{multiple_choice}'::text[],0.6) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-mp-16','ARM Thumb-2 Instruction Set','Hard','ECE','arena','interpret','Microprocessors & Controllers','multiple_choice','ARM Cortex-M processors use the Thumb-2 instruction set which mixes 16-bit and 32-bit instructions. The advantage is:','{"choices": ["Thumb-2 always executes faster than 32-bit ARM", "Thumb-2 achieves higher code density than 32-bit ARM (less flash needed) while matching 32-bit ARM performance — no mode switching required unlike original Thumb", "Thumb-2 uses 64-bit data types", "Thumb-2 is backward compatible with 8086"], "correct": 1}'::jsonb,'Original ARM: 32-bit instructions only (high performance). Original Thumb: 16-bit only (high density, lower performance). Thumb-2: both 16-bit and 32-bit instructions interleaved — ~26% smaller code than ARM32, ~98% performance of ARM32. No THUMB/ARM mode switching overhead.','{multiple_choice}'::text[],0.62) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-mp-17','Bootloader and Firmware Update','Hard','ECE','arena','select','Microprocessors & Controllers','multiple_choice','A secure bootloader in an embedded product verifies firmware integrity before executing it using:','{"choices": ["A simple checksum (8-bit XOR)", "Cryptographic signature verification (e.g., RSA-2048 or ECDSA) — only firmware signed with the manufacturer''s private key is accepted; prevents loading of malicious or corrupted firmware", "CRC-16 error detection", "Comparing file size to expected value"], "correct": 1}'::jsonb,'Secure boot chain: bootloader has manufacturer''s public key embedded in OTP. New firmware image includes its hash signed with manufacturer''s private key. Bootloader verifies signature before jumping to application. Prevents firmware tampering — critical for IoT security.','{multiple_choice}'::text[],0.58) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-mp-18','JTAG Boundary Scan','Hard','ECE','arena','interpret','Microprocessors & Controllers','multiple_choice','JTAG (IEEE 1149.1) boundary scan is used for:','{"choices": ["In-system programming and debugging only", "Testing PCB interconnects without physical probe access — each IC''s pins are connected in a scan chain; shifting test patterns through detects open/short circuit solder defects between ICs", "Real-time performance monitoring", "Bootloader programming only"], "correct": 1}'::jsonb,'JTAG Boundary Scan: BSR (Boundary Scan Register) cells at each I/O pin. Shift in test pattern → drives pins → sample results at adjacent IC → shift out. Detects: open solder joints, shorts between tracks, missing components. Essential for BGA packages (no physical probe access).','{multiple_choice}'::text[],0.6) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-mp-19','RTOS Context Switch Overhead','Hard','ECE','arena','calculate','Microprocessors & Controllers','multiple_choice','An ARM Cortex-M4 RTOS performs context switches at 1 kHz (every 1 ms). Context switch takes 200 clock cycles at 168 MHz. CPU overhead from context switching:
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-mp-20','Flash Memory Endurance in MCUs','Hard','ECE','arena','select','Microprocessors & Controllers','multiple_choice','An STM32 microcontroller has Flash endurance of 10,000 erase cycles. A firmware update system writes to Flash every hour. After how long will the Flash wear out?
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-mp-21','Cortex-M Fault Exceptions','Hard','ECE','arena','diagnose','Microprocessors & Controllers','multiple_choice','An ARM Cortex-M3 firmware triggers a HardFault at address 0x08001234. The most systematic first debug step is:','{"choices": ["Erase and re-flash the firmware", "Examine the stacked PC register (at SP+24) — this is the address of the instruction that caused the fault; decode the fault status registers (CFSR, HFSR) to determine fault type (bus fault, memory fault, usage fault)", "Increase the stack size", "Disable interrupts and retry"], "correct": 1}'::jsonb,'HardFault: CFSR (Configurable Fault Status Register) bits identify cause. UFSR: divide by zero, invalid instruction. BFSR: bus error. MMFSR: MPU violation. Stacked LR, PC, PSR reveal fault context. STM32CubeIDE''s fault analyser automates this.','{multiple_choice}'::text[],0.55) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-mp-22','Ethernet PHY and MAC','Hard','ECE','arena','interpret','Microprocessors & Controllers','multiple_choice','In an embedded system with Ethernet, the MAC (Media Access Controller) in the MCU communicates with an external PHY chip via:','{"choices": ["SPI interface", "I²C at 100 kHz", "RMII (Reduced Media Independent Interface) — 2-bit (Tx/Rx) interface at 50 MHz reference clock; PHY handles physical layer (analog TX/RX, auto-negotiation, scrambling)", "USB 2.0 interface"], "correct": 2}'::jsonb,'RMII: 7 signal interface (TXEN, TXD[1:0], CRS_DV, RXD[1:0], REF_CLK, MDC, MDIO). 100 Mbps = 50 MHz × 2 bits. MII (4-bit) also used. MDIO/MDC: management interface for PHY register configuration. PHY converts digital RMII to analog Ethernet signals.','{multiple_choice}'::text[],0.55) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-mp-23','USB HID vs CDC Device Class','Hard','ECE','arena','compare','Microprocessors & Controllers','multiple_choice','An embedded product that needs to appear as a virtual serial port (COM port) on the host PC should implement:','{"choices": ["USB HID (Human Interface Device) class", "USB MSC (Mass Storage Class)", "USB CDC-ACM (Communications Device Class - Abstract Control Model) — provides virtual COM port without custom drivers on Windows 10+/macOS/Linux", "USB Audio class"], "correct": 2}'::jsonb,'USB CDC-ACM: Windows 10+, macOS, Linux recognise it natively as a COM/tty port — no INF driver needed. Provides standard serial API (baud rate, handshaking). Used by Arduino, STM32 virtual COM. HID: keyboards/mice/gamecontrollers (no custom driver, but limited bandwidth and HID report format).','{multiple_choice}'::text[],0.62) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-mp-24','Power Consumption: Run vs Sleep Modes','Hard','ECE','arena','calculate','Microprocessors & Controllers','multiple_choice','An STM32L4 MCU: run mode = 28 µA/MHz at 4 MHz = 112 µA; stop2 mode = 0.9 µA. Application: 1% active (run at 4 MHz), 99% in Stop2. Average current:','{"choices": ["112 µA", "56.5 µA", "2.01 µA", "0.9 µA"], "correct": 2}'::jsonb,'I_avg = 0.01 × 112 µA + 0.99 × 0.9 µA = 1.12 + 0.89 = 2.01 µA. At 3 V: P = 6 µW. Battery life on 100 mAh coin cell: 100,000 µAh / 2.01 µA ≈ 49,750 hours ≈ 5.7 years.','{multiple_choice}'::text[],0.68) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-mp-25','Endianness: Big vs Little Endian','Hard','ECE','arena','interpret','Microprocessors & Controllers','multiple_choice','A 32-bit value 0x12345678 is stored at memory address 0x1000. In little-endian (ARM default), the bytes at addresses 0x1000, 0x1001, 0x1002, 0x1003 are:','{"choices": ["0x12, 0x34, 0x56, 0x78", "0x78, 0x56, 0x34, 0x12", "0x34, 0x12, 0x78, 0x56", "0x00, 0x00, 0x00, 0x78"], "correct": 1}'::jsonb,'Little-endian: least significant byte at lowest address. 0x12345678 → [0x1000]=0x78 (LSB), [0x1001]=0x56, [0x1002]=0x34, [0x1003]=0x12 (MSB). Big-endian: MSB at lowest address. Network byte order = big-endian → ARM code needs byte-swap (htonl/ntohl) for network protocols.','{multiple_choice}'::text[],0.72) ON CONFLICT (slug) DO NOTHING;
